import generate from '@babel/generator';
import * as t from '@babel/types';

export { t };

export const HEADER = [
  '/**',
  ' * Generated by pg-codegen. DO NOT EDIT.',
  ' */',
  '/* eslint-disable */',
  ''
].join('\n');

export const generateCode = (statements: t.Statement[]): string => {
  const program = t.program(statements);
  const { code } = generate(program, {
    jsescOption: { quotes: 'single' },
    retainLines: false
  });
  return `${HEADER}${code}\n`;
};

/** Attach a JSDoc block as a leading comment. */
export const withJsDoc = <T extends t.Statement>(node: T, text: string): T => {
  t.addComment(node, 'leading', `* ${text} `, false);
  return node;
};

export const namedImport = (names: string[], source: string): t.ImportDeclaration =>
  t.importDeclaration(
    names.map(name => t.importSpecifier(t.identifier(name), t.identifier(name))),
    t.stringLiteral(source)
  );

export const asConst = (expression: t.Expression): t.TSAsExpression =>
  t.tsAsExpression(expression, t.tsTypeReference(t.identifier('const')));

export const exportConst = (
  name: string,
  init: t.Expression,
  typeAnnotation?: t.TSType
): t.ExportNamedDeclaration => {
  const id = t.identifier(name);
  if (typeAnnotation) id.typeAnnotation = t.tsTypeAnnotation(typeAnnotation);
  return t.exportNamedDeclaration(
    t.variableDeclaration('const', [t.variableDeclarator(id, init)])
  );
};

/** `` `${label}.suffix` `` */
export const labelTemplate = (suffix: string): t.TemplateLiteral =>
  t.templateLiteral(
    [
      t.templateElement({ raw: '', cooked: '' }),
      t.templateElement({ raw: `.${suffix}`, cooked: `.${suffix}` }, true)
    ],
    [t.identifier('label')]
  );
